import { useLayoutEffect, useState } from "react";
import AnimatedDetails from "../../AnimatedDetails";
import type { WorkerRun } from "../../ConversationRuntime";
import type { TimelineEvent } from "../../timeline";
import { relativeFilePath } from "../../workspaceFiles";
import TurnDiff from "../TurnDiff";
import ToolItem from "./ToolItem";
import { ActivityIcon, Chevron } from "./Icons";
import { activitySummary, transcriptSummary, eventKey, eventView, text, workerIdentity, type DisplayItem, type EventViewMemory, type HistoryProps, type Quest, type Row } from "./eventModel";

export default function EventGroup({ item, quests, runs, memory, visible = true, transcript = false, onQuest, onOpenFile, onInspect, onOpenHistory, historyStats, connection, onHistoryLoaded }: { item: Extract<DisplayItem, { type: "group" }>; quests: Quest[]; runs: WorkerRun[]; memory: EventViewMemory; visible?: boolean; transcript?: boolean; onQuest: (id: string) => void; onOpenFile?: (path: string) => void; onInspect: () => void } & HistoryProps) {
  const [expanded, setExpanded] = useState(() => item.events.some((event) => eventView(memory, event).groupExpanded));
  const [filesExpanded, setFilesExpanded] = useState(() => item.events.some((event) => eventView(memory, event).groupFilesExpanded));
  // Members inherit the current group state, so splits and prepended group roots restore it.
  useLayoutEffect(() => {
    for (const event of item.events) {
      eventView(memory, event).groupExpanded = expanded;
      eventView(memory, event).groupFilesExpanded = filesExpanded;
    }
  }, [item.events, memory, expanded, filesExpanded]);
  const summary = transcript ? transcriptSummary(item.events, runs) : activitySummary(item.events, runs);
  const origins = [...new Set(item.events.map((event) => workerIdentity(event, runs)).filter(Boolean))];
  const hasMock = item.events.some((event) => event.execution_mode === "mock");
  const hasFailure = item.events.some((event) => /failed/.test(event.status || "") || typeof (event.detail as Row | undefined)?.exit_code === "number" && Number((event.detail as Row).exit_code) !== 0);
  const hasUnknown = item.events.some((event) => /unknown|uncertain/.test(event.status || ""));
  const recordedFiles = new Map<string, TimelineEvent>();
  for (const event of item.events) {
    const detail = event.detail && typeof event.detail === "object" ? event.detail as Row : {};
    if (event.kind !== "tool_receipt" || event.status !== "succeeded" || event.execution_mode !== "live" || typeof detail.exit_code === "number" && detail.exit_code !== 0 || !["file_write", "file_revise"].includes(text(detail.tool, "")) || typeof detail.path !== "string") continue;
    try { const path = relativeFilePath(detail.path); if (!recordedFiles.has(path)) recordedFiles.set(path, event); } catch { /* An invalid path is not an openable file reference. */ }
  }
  const files = [...recordedFiles.entries()];
  const turnFiles = files.map(([path, event]) => ({ path, receiptId: event.event_id, scrollKey: `file:${eventKey(event)}`, ...historyStats?.[event.event_id] }));
  const iconEvent = item.events.find(event => ["file_write", "file_revise"].includes(text((event.detail as Row | undefined)?.tool, ""))) || item.events[0];
  return <AnimatedDetails className={`event-group${transcript ? " process-tool-summary" : ""}`} scrollKey={`group:${eventKey(item.events[0])}`} initialExpanded={expanded} onExpandedChange={(value) => { for (const event of item.events) eventView(memory, event).groupExpanded = value; setExpanded(value); }} onInspect={onInspect} summaryTitle={origins.join("\n")} summary={<><ActivityIcon event={iconEvent} /><span className="event-label">{summary}</span>{hasFailure && <span className="event-risk event-failed">失败</span>}{hasUnknown && <span className="event-risk event-unknown">结果未知</span>}{hasMock && <small className="event-mode"> · {item.events.every((event) => event.execution_mode === "mock") ? "模拟" : "含模拟记录"}</small>}<Chevron /></>}>
    <div className="event-detail">{!transcript && <TurnDiff files={turnFiles} groupKey={eventKey(item.events[0])} initialExpanded={filesExpanded}
      onExpandedChange={(value) => { for (const event of item.events) eventView(memory, event).groupFilesExpanded = value; setFilesExpanded(value); }}
      onInspect={onInspect} onOpenFile={onOpenFile} onOpenHistory={onOpenHistory} />}{item.events.map((event) => <ToolItem key={eventKey(event)} event={event} quests={quests} runs={runs} memory={memory} groupExpanded={expanded && visible} onQuest={onQuest} onOpenFile={onOpenFile} onOpenHistory={onOpenHistory} historyStats={historyStats} connection={connection} onHistoryLoaded={onHistoryLoaded} onInspect={onInspect} />)}</div>
  </AnimatedDetails>;
}

import type { WorkerRun } from "./ConversationRuntime";
import type { DisplayItem } from "./components/conversation/eventModel";
import { messageMetadata, type ChatMessage, type TimelineEvent, type TimelineItem } from "./timeline.ts";

export type ProcessRecord =
  | { type: "message"; value: ChatMessage }
  | { type: "tools"; events: TimelineEvent[] }
  | { type: "agents"; events: TimelineEvent[]; runs: WorkerRun[] }
  | { type: "snapshot"; run: WorkerRun };

export interface ProcessGroup {
  type: "process";
  key: string;
  records: ProcessRecord[];
  active: boolean;
  runIds: string[];
  /** A displayed trailing reply, not a claim that the backend marked a turn complete. */
  answerId?: string;
  /** Reserved for an explicit persisted turn duration; timestamps alone do not supply it. */
  durationMs?: number;
}

export type ProcessTimelineItem = Exclude<TimelineItem, { type: "event" }> | ProcessGroup;
type OrderedItem = TimelineItem | { type: "snapshot"; run: WorkerRun };

const timestamp = (value: string | undefined) => {
  const parsed = Date.parse(value || "");
  return Number.isFinite(parsed) ? parsed : null;
};
const itemTime = (item: OrderedItem) => timestamp(item.type === "snapshot" ? item.run.created_at
  : item.type === "outgoing" ? item.value.createdAt : item.value.created_at);
const running = (run: WorkerRun) => run.state === "running" || run.state === "queued";
const lifecycle = (event: TimelineEvent) => event.kind === "event" && /^worker\./.test(event.status || "");
const itemKey = (item: OrderedItem) => item.type === "snapshot" ? `run:${item.run.run_id}`
  : item.type === "event" ? `event:${item.value.kind}:${item.value.event_id}`
    : item.type === "outgoing" ? `outgoing:${item.value.requestId}` : `message:${item.value.id}`;
const isUser = (item: OrderedItem) => item.type === "outgoing" || item.type === "message" && item.value.role === "user";
const canBeReply = (message: ChatMessage) => {
  const meta = messageMetadata(message.metadata);
  return message.role === "assistant" && meta.source !== "router_notice" && meta.phase !== "commentary" && meta.channel !== "commentary";
};

/** Chronological display windows do not assert task ownership or invent a completion fact. */
export function buildProcessTimeline(items: (TimelineItem | DisplayItem)[], workerRuns: WorkerRun[]): ProcessTimelineItem[] {
  const ordered: OrderedItem[] = items.flatMap(item => item.type === "group"
    ? item.events.map(value => ({ type: "event" as const, value })) : [item]);
  const runs = new Map(workerRuns.filter(run => typeof run.run_id === "string" && run.run_id).map(run => [run.run_id, run]));
  const recordedLifecycle = new Set(ordered.flatMap(item => item.type === "event" && lifecycle(item.value) && item.value.run_id ? [item.value.run_id] : []));
  // An activity snapshot has no terminal timestamp. Show it as current state only,
  // and leave every persisted event at its original position rather than adopting it.
  const snapshots: OrderedItem[] = [...runs.values()].filter(run => !recordedLifecycle.has(run.run_id))
    .map(run => ({ type: "snapshot" as const, run }));
  snapshots.sort((left, right) => {
    const first = itemTime(left), second = itemTime(right);
    return first !== null && second !== null ? first - second : first !== null ? -1 : second !== null ? 1 : 0;
  });
  for (const snapshot of snapshots) {
    const time = itemTime(snapshot);
    const position = time === null ? -1 : ordered.findIndex(item => {
      const other = itemTime(item);
      return other !== null && other > time;
    });
    if (position < 0) ordered.push(snapshot);
    else ordered.splice(position, 0, snapshot);
  }

  const output: ProcessTimelineItem[] = [];
  let segment: OrderedItem[] = [], boundary = "";
  const flush = () => {
    if (!segment.length) return;
    const hasEvents = segment.some(item => item.type === "event");
    // Ordinary messages stay ordinary when the only extra information is an
    // independently read activity snapshot; there is no recorded process to hide.
    if (!hasEvents) {
      let snapshotsOnly: OrderedItem[] = [];
      const flushSnapshots = () => {
        if (!snapshotsOnly.length) return;
        output.push(makeGroup(snapshotsOnly, `${boundary || itemKey(snapshotsOnly[0])}:${itemKey(snapshotsOnly[0])}`, runs));
        snapshotsOnly = [];
      };
      for (const item of segment) {
        if (item.type === "snapshot") snapshotsOnly.push(item);
        else { flushSnapshots(); if (item.type !== "event") output.push(item); }
      }
      flushSnapshots();
      segment = [];
      return;
    }
    const group = makeGroup(segment, boundary || itemKey(segment[0]), runs);
    const tail = segment[segment.length - 1];
    // The API does not expose a final channel. Only a trailing ordinary reply
    // may be displayed outside; a notice or progress message is never promoted.
    if (!group.active && tail.type === "message" && canBeReply(tail.value)) {
      group.answerId = tail.value.id;
      group.records = group.records.filter(record => !(record.type === "message" && record.value.id === tail.value.id));
      output.push(group, tail);
    } else output.push(group);
    segment = [];
  };
  for (const item of ordered) {
    if (isUser(item)) {
      flush();
      if (item.type === "message" || item.type === "outgoing") output.push(item);
      boundary = itemKey(item);
    } else segment.push(item);
  }
  flush();
  return output;
}

function makeGroup(items: OrderedItem[], key: string, runs: Map<string, WorkerRun>): ProcessGroup {
  const records: ProcessRecord[] = [];
  const runIds = new Set<string>();
  for (const item of items) {
    if (item.type === "snapshot") {
      runIds.add(item.run.run_id);
      records.push(item);
    } else if (item.type === "message") records.push(item);
    else if (item.type === "event") {
      const event = item.value;
      if (event.run_id) runIds.add(event.run_id);
      const previous = records[records.length - 1];
      if (lifecycle(event)) {
        const run = event.run_id ? runs.get(event.run_id) : undefined;
        if (previous?.type === "agents" && previous.events[0].status === event.status && previous.events[0].execution_mode === event.execution_mode) {
          previous.events.push(event);
          if (run && !previous.runs.some(item => item.run_id === run.run_id)) previous.runs.push(run);
        } else records.push({ type: "agents", events: [event], runs: run ? [run] : [] });
      } else if (previous?.type === "tools") previous.events.push(event);
      else records.push({ type: "tools", events: [event] });
    }
  }
  return { type: "process", key: `process:${key}`, records, active: [...runIds].some(id => {
    const run = runs.get(id);
    return !!run && running(run);
  }), runIds: [...runIds] };
}

